use rusqlite::{Connection, Result};
use csv::Writer;
use std::fs::File;

struct ReportRow {
    id: i32,
    name: String,
    department_id: i32,
    total_sales: i64,
    dept_rank: i64,
}

fn main() -> Result<()> {
    let conn = Connection::open("/home/user/company.db")?;

    let sql = "
        WITH RECURSIVE
          hierarchy(emp_id, sub_id) AS (
            SELECT id, id FROM employees
            UNION ALL
            SELECT h.emp_id, e.id
            FROM hierarchy h
            JOIN employees e ON e.manager_id = h.sub_id
          ),
          total_sales_cte AS (
            SELECT h.emp_id as id, SUM(e.individual_sales) as total_sales
            FROM hierarchy h
            JOIN employees e ON h.sub_id = e.id
            GROUP BY h.emp_id
          ),
          ranked_sales AS (
            SELECT 
              e.id, 
              e.name, 
              e.department_id, 
              t.total_sales,
              DENSE_RANK() OVER (
                PARTITION BY e.department_id 
                ORDER BY t.total_sales DESC
              ) as dept_rank
            FROM employees e
            JOIN total_sales_cte t ON e.id = t.id
          )
        SELECT id, name, department_id, total_sales, dept_rank
        FROM ranked_sales
        ORDER BY id ASC;
    ";

    let mut stmt = conn.prepare(sql)?;
    let rows = stmt.query_map([], |row| {
        Ok(ReportRow {
            id: row.get(0)?,
            name: row.get(1)?,
            department_id: row.get(2)?,
            total_sales: row.get(3)?,
            dept_rank: row.get(4)?,
        })
    })?;

    let mut wtr = Writer::from_path("/home/user/report.csv").map_err(|e| {
        rusqlite::Error::UnknownColumn(format!("CSV error: {}", e))
    })?;

    wtr.write_record(&["id", "name", "department_id", "total_sales", "dept_rank"]).map_err(|e| {
        rusqlite::Error::UnknownColumn(format!("CSV error: {}", e))
    })?;

    for row_result in rows {
        let row = row_result?;
        wtr.write_record(&[
            row.id.to_string(),
            row.name,
            row.department_id.to_string(),
            row.total_sales.to_string(),
            row.dept_rank.to_string(),
        ]).map_err(|e| {
            rusqlite::Error::UnknownColumn(format!("CSV error: {}", e))
        })?;
    }

    wtr.flush().map_err(|e| {
        rusqlite::Error::UnknownColumn(format!("CSV error: {}", e))
    })?;

    Ok(())
}
EOF
"}

