    name: String,
    department_id: i32,
    total_sales: i64,
    dept_rank: i32,
}

fn main() -> Result<(), Box<dyn Error>> {
    let conn = Connection::open("/home/user/company.db")?;

    let mut stmt = conn.prepare("
        WITH RECURSIVE
          hierarchy(id, descendant_id) AS (
            SELECT id, id FROM employees
            UNION ALL
            SELECT h.id, e.id
            FROM hierarchy h
            JOIN employees e ON e.manager_id = h.descendant_id
          ),
          total_sales_table AS (
            SELECT h.id, SUM(e.individual_sales) as total_sales
            FROM hierarchy h
            JOIN employees e ON h.descendant_id = e.id
            GROUP BY h.id
          ),
          ranked_sales AS (
            SELECT 
                e.id, 
                e.name, 
                e.department_id, 
                t.total_sales,
                DENSE_RANK() OVER (
                    PARTITION BY e.department_id 
                    ORDER BY t.total_sales DESC
                ) as dept_rank
            FROM employees e
            JOIN total_sales_table t ON e.id = t.id
          )
        SELECT id, name, department_id, total_sales, dept_rank
        FROM ranked_sales
        ORDER BY id ASC
    ")?;

    let rows = stmt.query_map([], |row| {
        Ok(ReportRow {
            id: row.get(0)?,
            name: row.get(1)?,
            department_id: row.get(2)?,
            total_sales: row.get(3)?,
            dept_rank: row.get(4)?,
